from sys import stdin
from math import gcd
from collections import defaultdict

def make_factors(limit):
	fac = [[1] for _ in range(limit + 1)]
	for f in range(2, limit + 1):
		for mf in range(f, limit + 1, f):
			fac[mf].append(f)
	return fac
inp = stdin.readline
T = int(inp())
ans = []
factors = make_factors(100000)
for tx in range(T):
	N = int(inp())
	avail = defaultdict(dict)
	comb = 0
	for (p, a) in enumerate(map(int, inp().split()), 1):
		g = gcd(p, a)
		demand = p // g
		supplyfac = factors[a // g]
		if demand in avail:
			for f in supplyfac:
				comb += avail[demand].get(f, 0)
		for f in supplyfac:
			afac = avail[f]
			if demand in afac:
				afac[demand] += 1
			else:
				afac[demand] = 1
	ans.append(comb)
print(*ans, sep='\n')
